class BiospecimenTypeEnum(EnumDefinitionImpl):

    Ascites = PermissibleValue(
        text="Ascites",
        description="""The accumulation of fluid in the peritoneal cavity, which may be serous, hemorrhagic, or the result of tumor metastasis to the peritoneum.""",
        meaning=NCIT["C12440"])
    Blood = PermissibleValue(
        text="Blood",
        description="Blood circulating throughout the body.",
        meaning=NCIT["C12434"])
    Cells = PermissibleValue(
        text="Cells",
        description="""The smallest units of living structure capable of independent existence, composed of a membrane-enclosed mass of protoplasm and containing a nucleus or nucleoid.""",
        meaning=NCIT["C12508"])
    DNA = PermissibleValue(
        text="DNA",
        description="""A long linear double-stranded polymer formed from nucleotides attached to a deoxyribose backbone and found in the nucleus of a cell; associated with the transmission of genetic information.""",
        meaning=NCIT["C449"])
    RNA = PermissibleValue(
        text="RNA",
        description="""Single-stranded long chain of nucleotides containing ribose. It is the end product of DNA transcription by the enzyme RNA polymerase. It is essential in protein synthesis.""",
        meaning=NCIT["C812"])
    Saliva = PermissibleValue(
        text="Saliva",
        description="""The watery fluid in the mouth made by the salivary glands. Saliva moistens food to help digestion and it helps protect the mouth against infections.""",
        meaning=NCIT["C12439"])
    Skin = PermissibleValue(
        text="Skin",
        description="""An organ that constitutes the external surface of the body. It consists of the epidermis, dermis, and skin appendages.""",
        meaning=NCIT["C12443"])
    Sputum = PermissibleValue(
        text="Sputum",
        description="""Material containing mucus, cellular debris, microorganisms and sometimes blood or pus. It is ejected through the mouth from the lungs, bronchi, and trachea.""",
        meaning=NCIT["C12444"])
    Stool = PermissibleValue(
        text="Stool",
        description="""The material discharged from the bowel during defecation. It consists of undigested food, intestinal mucus, epithelial cells, and bacteria.""",
        meaning=NCIT["C12437"])
    Tissue = PermissibleValue(
        text="Tissue",
        description="""An anatomical structure consisting of similarly specialized cells and intercellular matrix, aggregated according to genetically determined spatial relationships, performing a specific function.""",
        meaning=NCIT["C12433"])
    Unknown = PermissibleValue(
        text="Unknown",
        description="Not known, observed, recorded; or reported as unknown by the data contributor.",
        meaning=NCIT["C17998"])
    Urine = PermissibleValue(
        text="Urine",
        description="""The fluid that is excreted by the kidneys. It is stored in the bladder and discharged through the urethra.""",
        meaning=NCIT["C12437"])
    Xenograft = PermissibleValue(
        text="Xenograft",
        description="The transfer of cells, tissues, or organs from a donor into a recipient of another species.",
        meaning=NCIT["C12445"])

    _defn = EnumDefinition(
        name="BiospecimenTypeEnum",
    )

    @classmethod
    def _addvals(cls):
        setattr(cls, "Body Fluid or Substance",
            PermissibleValue(
                text="Body Fluid or Substance",
                description="""Liquid and semi liquid substances produced by living organisms to fulfill specific functions or excreted as waste; does not include hormones or enzymes.""",
                meaning=NCIT["C13238"]))
        setattr(cls, "Bone Marrow",
            PermissibleValue(
                text="Bone Marrow",
                description="""The soft, sponge-like tissue in the center of bones that produces white blood cells, red blood cells, and platelets.""",
                meaning=NCIT["C12435"]))
        setattr(cls, "Cell Line",
            PermissibleValue(
                text="Cell Line",
                description="""A permanently established cell culture that will proliferate indefinitely given appropriate fresh medium and space.""",
                meaning=NCIT["C12508"]))
        setattr(cls, "Central Nervous System",
            PermissibleValue(
                text="Central Nervous System",
                description="""The main information-processing organs of the nervous system, consisting of the brain, spinal cord, and meninges.""",
                meaning=NCIT["C12441"]))
        setattr(cls, "Mouth Rinse",
            PermissibleValue(
                text="Mouth Rinse",
                description="""A sample consisting of biological material from the buccal cavity. A collection solution is introduced into the mouth, swished around, and then collected.""",
                meaning=NCIT["C12442"]))
        setattr(cls, "Not Reported",
            PermissibleValue(
                text="Not Reported",
                description="Not provided or available.",
                meaning=NCIT["C48660"]))

class TimepointEnum(EnumDefinitionImpl):

    A = PermissibleValue(
        text="A",
        description="10 - 21 days after the last dose of AC")
    Adjuvant = PermissibleValue(
        text="Adjuvant",
        description="""An agent that enhances the activity or therapeutic effect of another pharmacologic substance without having much, if any, therapeutic impact by itself.""")
    B = PermissibleValue(
        text="B",
        description="3 months following randomization")
    C = PermissibleValue(
        text="C",
        description="6 months following randomization")
    C2D1 = PermissibleValue(
        text="C2D1",
        description="""Cycle 2, Day 1 (pre-dose) (for crossover patients, this refers to Cycle 2, Day 1 of combination therapy)""")
    C3D1 = PermissibleValue(
        text="C3D1",
        description="""Cycle 3, Day 1 (pre-dose) (for crossover patients, this refers to Cycle 3, Day 1 of combination therapy)""")
    Chemotherapy = PermissibleValue(
        text="Chemotherapy",
        description="""The use of synthetic or naturally-occurring chemicals for the treatment of diseases.  Although this term may be used to describe any therapy involving the use of chemical-based agents, it is most commonly used to refer to the variety of chemical-based agents employed to treat cancer.  Cancer chemotherapy works by arresting or killing the growth and spread of cancer cells.  Because cancer cells usually divide much faster than normal cells, they are often very sensitive to the inhibitory actions of chemotherapeutic agents.  Chemotherapy may also include agents that enhance immune function or alter hormonal activity. (NCI04)""")
